func runMCP(ctx context.Context, in io.Reader, out io.Writer, opts Options) error {
	reader := bufio.NewReader(in)
	for {
		msg, err := readMCPMessage(reader)
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		if msg.ID == nil {
